UPDATE public.quizzes SET questions = questions || '[{"id": 481, "question": "(481) Combien d''heures suppl\u00e9mentaires Jean a-t-il effectu\u00e9es ?", "options": ["5 heures", "Aucune, s''il est pay\u00e9 au mois", "2 heures", "7 heures"], "correct_index": 3, "casus": "Jean a effectu\u00e9 42 heures de travail effectif cette semaine. Son contrat ne pr\u00e9voit pas de convention de forfait.", "reference": "Article L3121-27", "article": "La dur\u00e9e l\u00e9gale du travail effectif des salari\u00e9s \u00e0 temps complet est fix\u00e9e \u00e0 trente-cinq heures par semaine."}, {"id": 482, "question": "(482) \u00c0 d\u00e9faut d''accord, quelle est la date de d\u00e9but de la p\u00e9riode de r\u00e9f\u00e9rence pour les cong\u00e9s ?", "options": ["1er janvier", "1er juin", "Date d''embauche", "1er septembre"], "correct_index": 1, "casus": "Dans l''entreprise X, il n''y a pas d''accord. Un salari\u00e9 demande quand commence l''acquisition de ses cong\u00e9s.", "reference": "Article L3141-10", "article": "Un accord d''entreprise ou d''\u00e9tablissement peut fixer le d\u00e9but de la p\u00e9riode de r\u00e9f\u00e9rence."}, {"id": 483, "question": "(483) L''employeur peut-il se r\u00e9tracter le 10\u00e8me jour apr\u00e8s la signature ?", "options": ["Non, le d\u00e9lai est de 7 jours", "Oui, le d\u00e9lai est de 15 jours calendaires", "Non, seul le salari\u00e9 peut se r\u00e9tracter", "Oui, mais il doit payer une indemnit\u00e9"], "correct_index": 1, "casus": "La rupture a \u00e9t\u00e9 sign\u00e9e le 1er du mois. L''employeur change d''avis le 10.", "reference": "Article L1237-13", "article": "\u00c0 compter de la date de la signature par les deux parties, chacune d''entre elles dispose d''un d\u00e9lai de quinze jours calendaires pour exercer son droit de r\u00e9tractation."}, {"id": 484, "question": "(484) Qui doit prouver que les agissements ne sont pas du harc\u00e8lement ?", "options": ["Le juge", "L''employeur (partie d\u00e9fenderesse)", "La salari\u00e9e exclusivement", "L''inspecteur du travail"], "correct_index": 1, "casus": "Une salari\u00e9e se plaint de brimades r\u00e9p\u00e9t\u00e9es. Elle apporte des emails et des t\u00e9moignages.", "reference": "Article L1154-1", "article": "Le salari\u00e9 pr\u00e9sente des \u00e9l\u00e9ments de fait laissant supposer l''existence d''un harc\u00e8lement. Au vu de ces \u00e9l\u00e9ments, il incombe \u00e0 la partie d\u00e9fenderesse de prouver que ces agissements ne constituent pas un harc\u00e8lement."}, {"id": 485, "question": "(485) Le licenciement pour ''incompatibilit\u00e9 d''humeur'' sans faits mat\u00e9riellement v\u00e9rifiables est-il valable ?", "options": ["Non, il manque une cause r\u00e9elle et s\u00e9rieuse", "Oui, c''est un motif personnel suffisant", "Oui, si c''est mentionn\u00e9 dans le contrat", "Seulement si le salari\u00e9 est cadre"], "correct_index": 0, "casus": "Un employeur licencie un salari\u00e9 pour ''incompatibilit\u00e9 d''humeur'' sans faits pr\u00e9cis. Le salari\u00e9 conteste.", "reference": "Article L1232-1", "article": "Tout licenciement pour motif personnel doit \u00eatre justifi\u00e9 par une cause r\u00e9elle et s\u00e9rieuse."}, {"id": 486, "question": "(486) Combien d''heures suppl\u00e9mentaires Jean a-t-il effectu\u00e9es ?", "options": ["7 heures", "2 heures", "Aucune, s''il est pay\u00e9 au mois", "5 heures"], "correct_index": 0, "casus": "Jean a effectu\u00e9 42 heures de travail effectif cette semaine. Son contrat ne pr\u00e9voit pas de convention de forfait.", "reference": "Article L3121-27", "article": "La dur\u00e9e l\u00e9gale du travail effectif des salari\u00e9s \u00e0 temps complet est fix\u00e9e \u00e0 trente-cinq heures par semaine."}, {"id": 487, "question": "(487) \u00c0 d\u00e9faut d''accord, quelle est la date de d\u00e9but de la p\u00e9riode de r\u00e9f\u00e9rence pour les cong\u00e9s ?", "options": ["Date d''embauche", "1er septembre", "1er juin", "1er janvier"], "correct_index": 2, "casus": "Dans l''entrepris